package net.minecraft.world.phys;public class AABB {public double minX,minY,minZ,maxX,maxY,maxZ;public AABB(double a,double b,double c,double d,double e,double f){minX=a;minY=b;minZ=c;maxX=d;maxY=e;maxZ=f;}public AABB move(double x,double y,double z){return new AABB(minX+x,minY+y,minZ+z,maxX+x,maxY+y,maxZ+z);}public AABB inflate(double n){return new AABB(minX-n,minY-n,minZ-n,maxX+n,maxY+n,maxZ+n);}}
